export function Logo(){return <svg className="sentriq-logo" width="33" height="36" viewBox="0 0 36 38" fill="none"><path d="M18 2L32 10V27L18 36L4 28V11L18 2Z" stroke="currentColor" strokeWidth="1.4"/><path d="M10 22L17 12L24 22M10 26L17 16L26 27" stroke="currentColor" strokeWidth="1.7" strokeLinejoin="round"/><path d="M5 30L12 26L21 30L31 25" stroke="currentColor" strokeWidth="1.3"/></svg>}
export function MiniMetric({label,value,unit}:any){return <div className="mini-metric"><span>{label}</span><strong>{value}<small>{unit}</small></strong></div>}
function FloodMetric({label,estimate,scale=1,unit}:{label:string;estimate:{value:number|null;low:number|null;high:number|null};scale?:number;unit:string}){const value=estimate.value===null?'—':nf(estimate.value*scale),range=estimate.low===null||estimate.high===null?'—':`${nf(estimate.low*scale)}–${nf(estimate.high*scale)}`;return <div className="mini-metric"><span>{label}</span><strong>{value}<small>{unit}</small></strong><small>{uiText.floodQuery.range}: {range} {unit}</small></div>}

function DirectRunMetrics({floodQuery,impactData}:{floodQuery:FloodQueryResponse;impactData:ImpactResponse|null}){
  const downstream=impactData?.warning_table?.[0];
  return <>
    <FloodMetric label={uiText.floodQuery.area} estimate={floodQuery.summary.inundated_area_m2} scale={1e-6} unit="km²"/>
    {downstream?<><FloodMetric label={uiText.floodQuery.downstreamDepth.replace('{name}',downstream.name)} estimate={downstream.depth_m} unit="m"/><FloodMetric label={uiText.floodQuery.downstreamVelocity.replace('{name}',downstream.name)} estimate={downstream.velocity_ms} unit="m/s"/></>:null}
    <div className="mini-metric domain-max-note"><span>{uiText.floodQuery.domainMaxNote}</span><strong>{floodQuery.summary.max_depth_m.value===null?'—':nf(floodQuery.summary.max_depth_m.value)}<small>m</small> · {floodQuery.summary.max_velocity_ms.value===null?'—':nf(floodQuery.summary.max_velocity_ms.value)}<small>m/s</small></strong><small>{uiText.floodQuery.domainMaxNoteDetail}</small></div>
  </>;
}

function EstimateText({estimate}:{estimate:{value:number|null;low:number|null;high:number|null;unit:string|null}}){const fmt=(v:number|null)=>v===null?'—':nf(v);return <>{fmt(estimate.value)}{estimate.low!==null&&estimate.high!==null?` (${fmt(estimate.low)}–${fmt(estimate.high)})`:''}{estimate.unit?` ${estimate.unit}`:''}</>}
function ImpactMetric({label,estimate}:{label:string;estimate:{value:number|null;low:number|null;high:number|null;unit:string|null}}){return <div className="mini-metric"><span>{label}</span><strong>{estimate.value===null?'—':nf(estimate.value)}<small>{estimate.unit}</small></strong><small>{uiText.floodQuery.range}: {estimate.low===null||estimate.high===null?'—':`${nf(estimate.low)}–${nf(estimate.high)}`} {estimate.unit}</small></div>}
function ImpactCountsMetric({label,high,possible,unit}:{label:string;high:number;possible:number;unit:string}){return <div className="mini-metric"><span>{label}</span><strong>{nf(high+possible,0)}<small>{unit}</small></strong><small>{uiText.impact.high}: {nf(high,0)} · {uiText.impact.possible}: {nf(possible,0)}</small></div>}
function ImpactRangeMetric({label,value,range,unit}:{label:string;value:string;range:string;unit:string}){return <div className="mini-metric"><span>{label}</span><strong>{value}<small>{unit}</small></strong><small>{range}</small></div>}

function metric(value:number|undefined){return value===undefined||!Number.isFinite(value)?'—':nf(value,3)}
